# 36 veterinary and pet brands: (slug, name, url, verified fact, observation 1, observation 2, slide notes)
import json, os
_P = os.path.join(os.path.dirname(__file__), 'notes.json')
_N = json.load(open(_P)) if os.path.exists(_P) else {}
_B = [
# Vet clinics and hospitals
("banfield-pet-hospital","Banfield Pet Hospital","https://www.banfield.com/","Banfield was founded in Portland, Oregon, in 1955 and is now part of Mars Veterinary Health.","An orange medical cross has a dog and a cat cut into it, so the symbol says both care and pets.","The name sits over two lines, with Banfield in teal and \"Pet Hospital\" in grey capitals."),
("vca-animal-hospitals","VCA Animal Hospitals","https://vcahospitals.com/","VCA was founded in Los Angeles in 1986 and is now owned by Mars.","Heavy navy lowercase letters make the three initials the main part of the logo.","A small cluster of purple, teal and coral diamonds adds colour and works as a friendly symbol."),
("bluepearl-pet-hospital","BluePearl Pet Hospital","https://bluepearlvet.com/","BluePearl was founded in Tampa, Florida, in 1996 and runs specialty and emergency animal hospitals.","A short blue swoosh sits on the B like a tick, the only symbol in the logo.","A two-line wordmark in navy and bright blue keeps the long name compact."),
("thrive-pet-healthcare","Thrive Pet Healthcare","https://www.thrivepetcare.com/","Pathway Vet Alliance renamed itself Thrive Pet Healthcare in 2022.","The v in the name is drawn as a green pet face with two ears, a clever hidden symbol.","Bright blue lowercase letters and a green tagline line make the brand feel optimistic."),
("bond-vet","Bond Vet","https://bondvet.com/","Bond Vet was founded in New York in 2018 and runs urgent and primary care clinics.","A coral heart shape doubles as a pet face with two pointed ears.","Navy and coral split the name in two, so Bond and Vet read as separate words."),
("small-door-veterinary","Small Door Veterinary","https://www.smalldoorvet.com/","Small Door opened its first practice in Manhattan in 2019 as a membership-based vet.","A rounded, friendly serif in lowercase sets the name like a boutique hotel.","\"Veterinary\" is set in tiny, widely spaced capitals underneath, almost like a tagline."),
("modern-animal","Modern Animal","https://www.modernanimal.com/","Modern Animal was founded in Los Angeles in 2018 as a membership-based vet clinic.","A heavy serif in dark brown feels warm and premium rather than clinical.","Small spaced capitals for \"Veterinary Care\" sit underneath, so the brand name leads."),
("medivet","Medivet","https://www.medivet.co.uk/","Medivet was founded in 1987 and runs hundreds of vet practices across the UK.","A small pink M above the name hides a pet's face, with ears at the top and a nose in the middle.","Blue lettering and the line \"& Partners\" show that local vets co-own the practices."),
("vets4pets","Vets4Pets","https://www.vets4pets.com/","Vets4Pets is a UK chain of vet practices owned by Pets at Home.","Two greens split the name, with dark green for Vets and bright green for Pets.","A small, light \"for\" replaces the 4, which makes the name easy to read aloud."),
# Animal health and pet insurance
("zoetis","Zoetis","https://www.zoetis.com/","Zoetis was spun off from Pfizer in 2013 and is the world's largest animal health company.","Bright orange lowercase letters make the brand feel friendly for a pharmaceutical company.","The z has a looping tail, a small flourish that gives the wordmark its own character."),
("elanco","Elanco","https://www.elanco.com/","Elanco began as an agricultural division of Eli Lilly and became an independent company in 2019.","White italic letters sit inside a blue box that slants upward.","The slanted box suggests forward movement and works as a compact badge on packs."),
("idexx","IDEXX","https://www.idexx.com/","IDEXX was founded in Maine in 1983 and makes diagnostic tests and lab equipment for vets.","Heavy black capitals have small cuts in the letters, which makes them look engineered.","\"Laboratories\" is spaced wide underneath, matching the width of the name."),
("covetrus","Covetrus","https://covetrus.com/","Covetrus was formed in 2019 by combining Henry Schein Animal Health and Vets First Choice.","Navy lowercase letters keep the made-up name readable and calm.","A folded ribbon in red, navy and teal adds colour at the end of the name."),
("merck-animal-health","Merck Animal Health","https://www.merck-animal-health-usa.com/","Merck Animal Health is known as MSD Animal Health outside the United States and Canada.","The teal Merck symbol of circles and shapes is shared with the human health business.","\"Animal Health\" sits under MERCK in a lighter weight to separate the division from the parent."),
("hills-pet-nutrition","Hill's Pet Nutrition","https://www.hillspet.com/","Hill's is based in Topeka, Kansas, and has been owned by Colgate-Palmolive since 1976.","A red and navy H with a white swoosh looks like a flag and gives the brand a strong symbol.","A heavy serif sets Hill's under the mark, giving the brand a classic, trustworthy tone."),
("royal-canin","Royal Canin","https://www.royalcanin.com/us","Royal Canin was founded in France in 1968 by vet Jean Cathary and has been owned by Mars since 2001.","A red crown made of dots sits above the name and hints at the royal in the name.","Bold red capitals make the logo stand out on shelves and in vet clinics."),
("manypets","ManyPets","https://www.manypets.com/us/","The London-based insurer Bought By Many renamed itself ManyPets in 2021.","Dark green letters with rounded ends look soft and approachable.","Joining the two words with a capital P keeps the name short and easy to read."),
("pumpkin","Pumpkin","https://www.pumpkin.care/","Pumpkin is a New York pet insurer founded in 2019.","Heavy, wide capitals in dark plum look bold and confident.","There is no symbol or orange, so the friendly name does all the work."),
# Dog brands
("barkbox","BarkBox","https://www.barkbox.com/","BarkBox launched in New York in 2012, and its parent company now uses the name BARK.","Heavy black capitals look like they were cut from paper.","Three short lines after the K look like a bark or a wagging tail."),
("rover","Rover","https://www.rover.com/","Rover was founded in Seattle in 2011 and connects dog owners with sitters and walkers.","A green paw print sits before the name and works as the app icon.","A bold, slanted script makes the wordmark feel lively and friendly."),
("wag","Wag!","https://wagwalking.com/","Wag! was founded in 2015 and lets owners book dog walkers through an app.","Very heavy green letters fill the space and are easy to read on small screens.","The exclamation mark is part of the name and adds energy."),
("the-farmers-dog","The Farmer's Dog","https://www.thefarmersdog.com/","The Farmer's Dog was founded in New York in 2014 and delivers fresh dog food.","Hand-drawn white lettering sits inside a round coral badge.","The badge looks like a food label or a stamp, which fits a fresh food brand."),
("ollie","Ollie","https://www.myollie.com/","Ollie was founded in New York in 2016 and delivers fresh dog food.","Heavy, condensed black letters fill the logo with no symbol.","The tall letters make the short name feel bold and modern."),
("pedigree","Pedigree","https://www.pedigree.com/","Pedigree is one of the biggest dog food brands owned by Mars.","A blue show rosette sits behind the name, a nod to prize-winning dogs.","White slab-serif letters are designed for the brand's yellow packs, so the logo needs a coloured background."),
("milk-bone","Milk-Bone","https://www.milkbone.com/","Milk-Bone biscuits were first made in New York in 1908.","The logo sits inside a bone shape, so the product and the brand are the same picture.","A small red heart replaces the hyphen between Milk and Bone."),
("fi","Fi","https://tryfi.com/","Fi was founded in New York in 2017 and makes GPS collars for dogs.","Just two black italic letters make one of the shortest logos in the list.","The heavy slant gives the two letters a sense of speed, which suits a tracking device."),
("kong","KONG","https://www.kongcompany.com/","KONG was founded in Colorado in 1976 and is known for its rubber dog toys.","Heavy red capitals are tightly spaced like a toy brand.","The red toy shape at the end of the name is the product itself."),
# Cat brands
("whiskas","Whiskas","https://www.whiskas.co.uk/","Whiskas is a Mars cat food brand that has been sold in the UK since 1958.","White lowercase letters sit inside a bright purple box.","A darker purple cat's head with two pointed ears is drawn behind the name."),
("meow-mix","Meow Mix","https://www.meowmix.com/","Meow Mix was launched in 1974.","Bouncy, uneven letters look like they are moving to the brand's jingle.","Orange-red letters are stacked on two lines, which makes the logo compact on packs."),
("friskies","Friskies","https://www.purina.com/brands/friskies","Friskies is one of Nestlé Purina's best-known cat food brands.","Red letters with a yellow outline sit on a yellow banner.","A small Purina badge and the line \"Feed The Senses\" connect it to its parent brand."),
("sheba","Sheba","https://www.sheba.com/","Sheba is a Mars cat food brand sold in small trays and pouches.","A gold shield gives the brand a luxury feel, with a small black cat sitting on top of the S.","A thin script name runs across the shield like a signature."),
("9lives","9Lives","https://www.9lives.com/","9Lives was launched in 1959, and Morris the Cat has been its mascot since 1969.","A big 9 turns into the script word Lives.","Curved lines of small text, \"Caring for cats\" and \"Since 1959\", frame the name like a badge."),
("temptations","Temptations","https://www.temptationstreats.com/","Temptations is a cat treat brand owned by Mars.","A thick yellow outline wraps the name like a speech bubble.","Black italic letters make the name look fun and playful."),
("felix","Felix","https://www.purina.co.uk/felix","Felix is a Nestlé Purina cat food brand that was relaunched in the UK in 1989 with its black and white cat mascot.","Black lowercase script letters look like they were written with a brush.","Red paw prints over the x and a small Purina badge complete the logo."),
("smalls","Smalls","https://www.smalls.com/","Smalls was founded in New York in 2017 and delivers fresh cat food.","Thin, wide capitals are spaced far apart and look like a fashion brand.","With no symbol or colour, the logo feels premium rather than cute."),
("litter-robot","Litter-Robot","https://www.litter-robot.com/","Litter-Robot was created in Michigan in 2000 and is now made by Whisker.","A dot replaces the hyphen in the name, like a small piece of technology.","The line \"by whisker\" underneath shows the parent brand."),
]
B = [t + (_N.get(t[0], []),) for t in _B]
assert len(B) == 36
